class Solution {
  public int[] countMentions(int numberOfUsers, List<List<String>> events) {
    List<List<String>> sorted = new ArrayList<>(events);
    // status changes are processed before messages that share a timestamp
    sorted.sort(
        (a, b) -> {
          int ta = Integer.parseInt(a.get(1)), tb = Integer.parseInt(b.get(1));
          if (ta != tb) return Integer.compare(ta, tb);
          return Boolean.compare(a.get(0).equals("MESSAGE"), b.get(0).equals("MESSAGE"));
        });
    int[] mentions = new int[numberOfUsers];
    int[] onlineAt = new int[numberOfUsers];
    int allMentions = 0;
    for (List<String> e : sorted) {
      int time = Integer.parseInt(e.get(1));
      if (e.get(0).equals("OFFLINE")) {
        onlineAt[Integer.parseInt(e.get(2))] = time + 60;
        continue;
      }
      String text = e.get(2);
      if (text.equals("ALL")) {
        allMentions++;
      } else if (text.equals("HERE")) {
        for (int u = 0; u < numberOfUsers; u++) if (onlineAt[u] <= time) mentions[u]++;
      } else {
        for (String token : text.split(" ")) mentions[Integer.parseInt(token.substring(2))]++;
      }
    }
    for (int u = 0; u < numberOfUsers; u++) mentions[u] += allMentions;
    return mentions;
  }
}
